const d = $input.first().json;
const WL = ['display_name','birth_date','sex','height_cm','timezone','units','main_goal','goal_targets','goal_deadline','motivation','disciplines','experience_level','equipment','days_per_week','session_minutes','diet_type','target_kcal','target_protein_g','target_fat_g','target_carb_g','cooking_time_pref','cooking_skill','current_weight_kg','current_weight_on','onboarding_done','onboarding_safety_done'];
let obj = {};
try { obj = (typeof d.updates === 'string') ? JSON.parse(d.updates) : (d.updates || {}); } catch (e) { obj = {}; }
if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) obj = {};
const clean = {};
for (const k of WL) { const v = obj[k]; if (v !== undefined && v !== null && v !== '') clean[k] = v; }
return [{ json: { bot_id: d.bot_id, user_id: d.user_id, payload: JSON.stringify(clean), saved_fields: Object.keys(clean) } }];
